smart.css:
.smc-root {
  font-family: var(--smc-font-body, sans-serif);
  color: var(--smc-text);
  line-height: 1.72;
  font-size: 16px;
}

.smc-article {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.smc-article p {
  margin: 0;
}

.smc-article > p:first-of-type,
.smc-article > p:nth-of-type(2) {
  padding: 18px 20px;
  background: color-mix(in srgb, var(--smc-primary) 7%, var(--smc-bg));
  border-left: 4px solid var(--smc-primary);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
}

.smc-article h2 {
  margin: 24px 0 0;
  padding: 0 0 9px;
  color: var(--smc-primary);
  font-family: var(--smc-font-heading, sans-serif);
  font-size: 1.45rem;
  line-height: 1.35;
  border-bottom: 2px solid color-mix(in srgb, var(--smc-primary) 22%, var(--smc-border));
}

.smc-article h3 {
  margin: 12px 0 0;
  color: var(--smc-accent);
  font-family: var(--smc-font-heading, sans-serif);
  font-size: 1.08rem;
  line-height: 1.4;
}

.smc-article a {
  color: var(--smc-primary);
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--smc-primary) 35%, transparent);
  text-underline-offset: 3px;
}

.smc-article a:hover {
  text-decoration-color: var(--smc-primary);
}

.smc-article strong {
  font-weight: 650;
  color: var(--smc-text);
}

@container smc (max-width: 600px) {
  .smc-root {
    font-size: 15px;
    line-height: 1.65;
  }

  .smc-article {
    gap: 14px;
  }

  .smc-article > p:first-of-type,
  .smc-article > p:nth-of-type(2) {
    padding: 14px 15px;
  }

  .smc-article h2 {
    margin-top: 18px;
    font-size: 1.22rem;
  }

  .smc-article h3 {
    font-size: 1rem;
  }
}

